-- Private application schema: not exposed to anonymous browser clients.

CREATE SCHEMA IF NOT EXISTS daesatu;

REVOKE ALL ON SCHEMA daesatu FROM PUBLIC, anon, authenticated;

CREATE TABLE IF NOT EXISTS daesatu."orgs" (
  "id" TEXT PRIMARY KEY,
  "name" TEXT NOT NULL,
  "domains" TEXT NOT NULL DEFAULT '[]'
);

ALTER TABLE daesatu."orgs" ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON daesatu."orgs" FROM PUBLIC, anon, authenticated;

CREATE TABLE IF NOT EXISTS daesatu."users" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "org_id" TEXT NOT NULL,
  "employee_id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "password" TEXT NOT NULL,
  "role" TEXT NOT NULL DEFAULT 'user',
  "status" TEXT NOT NULL DEFAULT 'pending',
  "method" TEXT NOT NULL,
  "contact" TEXT NOT NULL,
  "verified" BIGINT NOT NULL DEFAULT 0,
  "reason" TEXT NOT NULL DEFAULT '',
  "affiliation_note" TEXT NOT NULL DEFAULT '',
  "totp_secret" TEXT,
  "totp_last" BIGINT NOT NULL DEFAULT -1,
  "consent_at" BIGINT NOT NULL,
  "created_at" BIGINT NOT NULL,
  "direct_login" BIGINT NOT NULL DEFAULT 0,
  "role_label" TEXT NOT NULL DEFAULT '',
  UNIQUE (org_id, employee_id)
);

ALTER TABLE daesatu."users" ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON daesatu."users" FROM PUBLIC, anon, authenticated;

CREATE TABLE IF NOT EXISTS daesatu."sessions" (
  "token" TEXT PRIMARY KEY,
  "user_id" BIGINT,
  "csrf" TEXT NOT NULL,
  "expires" BIGINT NOT NULL,
  "scope" TEXT NOT NULL DEFAULT 'normal'
);

ALTER TABLE daesatu."sessions" ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON daesatu."sessions" FROM PUBLIC, anon, authenticated;

CREATE TABLE IF NOT EXISTS daesatu."challenges" (
  "user_id" BIGINT PRIMARY KEY,
  "hash" TEXT NOT NULL,
  "expires" BIGINT NOT NULL,
  "attempts" BIGINT NOT NULL DEFAULT 0,
  "sent_at" BIGINT NOT NULL
);

ALTER TABLE daesatu."challenges" ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON daesatu."challenges" FROM PUBLIC, anon, authenticated;

CREATE TABLE IF NOT EXISTS daesatu."workspaces" (
  "user_id" BIGINT PRIMARY KEY,
  "data" TEXT NOT NULL,
  "updated_at" BIGINT NOT NULL
);

ALTER TABLE daesatu."workspaces" ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON daesatu."workspaces" FROM PUBLIC, anon, authenticated;

CREATE TABLE IF NOT EXISTS daesatu."audit" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "actor" BIGINT,
  "action" TEXT NOT NULL,
  "target" BIGINT,
  "detail" TEXT NOT NULL,
  "created_at" BIGINT NOT NULL
);

ALTER TABLE daesatu."audit" ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON daesatu."audit" FROM PUBLIC, anon, authenticated;

CREATE TABLE IF NOT EXISTS daesatu."rates" (
  "key" TEXT NOT NULL,
  "created_at" BIGINT NOT NULL
);

ALTER TABLE daesatu."rates" ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON daesatu."rates" FROM PUBLIC, anon, authenticated;

CREATE TABLE IF NOT EXISTS daesatu."attachments" (
  "id" TEXT PRIMARY KEY,
  "user_id" BIGINT NOT NULL,
  "name" TEXT NOT NULL,
  "size" BIGINT NOT NULL,
  "format" TEXT NOT NULL,
  "text" TEXT NOT NULL,
  "truncated" BIGINT NOT NULL,
  "created_at" BIGINT NOT NULL
);

ALTER TABLE daesatu."attachments" ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON daesatu."attachments" FROM PUBLIC, anon, authenticated;

CREATE INDEX IF NOT EXISTS rates_key ON daesatu.rates(key,created_at);

CREATE INDEX IF NOT EXISTS attachments_user ON daesatu.attachments(user_id);
